RSpec.describe TimekeepingRules::ReservationDecision, ".call" do
  it "releases nothing on a non-draft invoice even when the desired set drops a committed entry" do
    held = [{ invoice: :this, state: "committed", disposition: "active" }]
    current = { 10 => held, 11 => held, 12 => held }

    # "On a non-draft invoice the decision releases nothing (row L4: \"On a non-draft, the boundary sends no removal\")."
    decision = described_class.call(current:, desired: [10], disposition: "active", invoice_status: "sent")

    expect(decision[:release]).to eq([])
    expect(decision[:reserve]).to eq([])
    expect(decision[:conflicts]).to eq([])

    # The same drop on a draft does release, so the empty release above comes from the status.
    draft = described_class.call(current:, desired: [10], disposition: "active", invoice_status: "draft")
    expect(draft[:release]).to contain_exactly(11, 12)

    # A caller that wrongly sends an empty set for a sent invoice must not unlock the entries it holds.
    emptied = described_class.call(current:, desired: [], disposition: "active", invoice_status: "sent")
    expect(emptied[:release]).to eq([])
    expect(emptied[:reserve]).to eq([])
    expect(emptied[:conflicts]).to eq([])
  end
end

RSpec.describe TimekeepingRules::ReservationDecision, ".call" do
  it "releases on a draft only the entries no remaining direct or grouped line references" do
    held = [{ invoice: :this, state: "committed", disposition: "active" }]
    current = { 1 => held, 2 => held, 3 => held, 4 => held }
    # Remaining lines: a direct line for entry 1 and a grouped line for entries 2 and 3.
    # Entry 4's line was removed.
    desired = [1, [2, 3]]

    # "A draft's removed line releases only entries no remaining direct or grouped line references."
    decision = described_class.call(current:, desired:, disposition: "active", invoice_status: "draft")

    expect(decision[:release]).to eq([4])
    expect(decision[:reserve]).to eq([])
    expect(decision[:conflicts]).to eq([])
  end
end

RSpec.describe TimekeepingRules::ReservationDecision, ".call" do
  it "refuses an entry another kept invoice holds and decides every row of the prepare table" do
    current = {
      1 => [],
      2 => [{ invoice: :this, state: "committed", disposition: "active" }],
      3 => [{ invoice: :other, state: "committed", disposition: "active" }],
      4 => [{ invoice: :other, state: "committed", disposition: "retained" }],
      5 => [{ invoice: :other, state: "provisional", disposition: "active" }]
    }

    decision = described_class.call(current:, desired: [1, 2, 3, 4, 5, 6], disposition: "active", invoice_status: "draft")

    # "prepare reserves new entries provisionally and keeps committed ones"
    expect(decision[:reserve]).to contain_exactly(1, 4)
    # "An entry another kept invoice holds is refused: \"Prepare is refused: the entry is on another invoice.\""
    # Entry 6 is not in current, so it is outside the company.
    expect(decision[:conflicts].map { |conflict| [conflict[:entry_id], conflict[:reason].to_s] }).to contain_exactly(
      [3, "on_another_invoice"], [5, "provisional_elsewhere"], [6, "not_found"]
    )
    expect(decision[:release]).to eq([])
  end
end

RSpec.describe TimekeepingRules::ReservationDecision, ".call" do
  it "keeps every reservation when the disposition is retained" do
    held = [{ invoice: :this, state: "committed", disposition: "active" }]

    # "`disposition: \"retained\"` keeps a discarded or destroyed non-draft's reservations."
    decision = described_class.call(current: { 1 => held, 2 => held }, desired: [], disposition: "retained",
                                    invoice_status: "draft")

    expect(decision[:release]).to eq([])
    expect(decision[:conflicts]).to eq([])

    # Rows that are themselves marked retained stay held too.
    retained_row = [{ invoice: :this, state: "committed", disposition: "retained" }]
    kept = described_class.call(current: { 3 => retained_row }, desired: [], disposition: "retained",
                                invoice_status: "draft")
    expect(kept[:release]).to eq([])
  end
end

